import React, { useState, useRef } from 'react';
import { compressImage, compressVideo, createVideoThumbnail } from '../../utils/mediaCompression';

const MediaUploader = ({ 
  type, 
  multiple, 
  onUpload, 
  uploadedFiles, 
  setUploadedFiles, 
  disabled 
}) => {
  const [isCompressing, setIsCompressing] = useState(false);
  const [compressionProgress, setCompressionProgress] = useState(0);
  const fileInputRef = useRef(null);

  const handleClick = () => {
      fileInputRef.current.click();
  };

  const handleFilesChange = async (e) => {
    if (disabled) return;
    
    const files = Array.from(e.target.files);
    if (files.length === 0) return;
    
    setIsCompressing(true);
    setCompressionProgress(0);
    
    try {
      let processedFiles = [];
      
      // Process each file
      for (let i = 0; i < files.length; i++) {
        const file = files[i];
        
        // Update progress
        setCompressionProgress(Math.round((i / files.length) * 50));
        
        if (type === 'image') {
          // Compress image
          const compressedFile = await compressImage(file, 0.6); // 60% quality
          processedFiles.push({
            file: compressedFile,
            preview: URL.createObjectURL(compressedFile)
          });
        } else if (type === 'video') {
          // Generate thumbnail first for immediate feedback
          const thumbnailBlob = await createVideoThumbnail(file);
          const thumbnail = URL.createObjectURL(thumbnailBlob);
          
          // Show the thumbnail while compressing
          const tempFile = {
            file,
            preview: thumbnail,
            isCompressing: true
          };
          
          setUploadedFiles([tempFile]);
          
          // Compress video (may take some time)
          setCompressionProgress(60);
          const compressedFile = await compressVideo(file);
          setCompressionProgress(90);
          
          // Replace with compressed video
          processedFiles.push({
            file: compressedFile,
            preview: thumbnail,
            videoUrl: URL.createObjectURL(compressedFile)
          });
        }
      }
      
      // Update the state with processed files
      if (multiple) {
        setUploadedFiles([...uploadedFiles, ...processedFiles]);
      } else {
        setUploadedFiles(processedFiles);
      }
      
      // Notify parent component
      onUpload(multiple ? processedFiles.map(f => f.file) : processedFiles[0].file);
      
    } catch (error) {
      console.error('Error processing files:', error);
    } finally {
      setIsCompressing(false);
      setCompressionProgress(100);
      
      // Reset the file input
      e.target.value = '';
    }
  };

  const removeFile = (index) => {
    if (disabled) return;
    
    const newFiles = [...uploadedFiles];
    
    // Revoke object URL to prevent memory leaks
    if (newFiles[index].preview) {
      URL.revokeObjectURL(newFiles[index].preview);
    }
    if (newFiles[index].videoUrl) {
      URL.revokeObjectURL(newFiles[index].videoUrl);
    }
    
    newFiles.splice(index, 1);
    setUploadedFiles(newFiles);
  };

  const getAcceptAttribute = () => {
      if (type === 'image') return 'image/*';
      if (type === 'video') return 'video/*';
      return '';
  };

  return (
    <div className="bg-gray-50 border-2 border-dashed border-gray-300 rounded-md p-4">
      {uploadedFiles.length > 0 ? (
        <div className="grid grid-cols-2 gap-2">
          {uploadedFiles.map((fileObj, index) => (
            <div key={index} className="relative">
              {type === 'image' ? (
                <img 
                  src={fileObj.preview} 
                  alt={`Upload ${index}`}
                  className="w-full h-32 object-cover rounded-md"
                />
              ) : (
                <div className="relative">
                  <div className="w-full h-32 bg-black rounded-md overflow-hidden">
                    {fileObj.videoUrl ? (
                      <video 
                        src={fileObj.videoUrl} 
                        poster={fileObj.preview}
                        className="w-full h-full object-cover" 
                        controls
                      />
                    ) : (
                      <img 
                        src={fileObj.preview} 
                        alt="Video thumbnail" 
                        className="w-full h-full object-cover"
                      />
                    )}
                  </div>
                  {fileObj.isCompressing && (
                    <div className="absolute inset-0 flex items-center justify-center bg-black bg-opacity-50 rounded-md">
                      <div className="text-center">
                        <div className="inline-block animate-spin rounded-full h-8 w-8 border-4 border-white border-t-transparent"></div>
                        <p className="text-white text-sm mt-2">Compressing...</p>
                      </div>
                    </div>
                  )}
                </div>
              )}
              {!disabled && (
                <button 
                  className="absolute top-1 right-1 bg-red-500 text-white rounded-full p-1 hover:bg-red-600"
                  onClick={() => removeFile(index)}
                >
                  <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
                  </svg>
                </button>
              )}
            </div>
          ))}
          {multiple && (
            <label className="border-2 border-dashed border-gray-300 rounded-md flex flex-col items-center justify-center h-32 cursor-pointer hover:bg-gray-100">
              <input
                type="file"
                accept={type === 'image' ? 'image/*' : 'video/*'}
                onChange={handleFilesChange}
                multiple={multiple}
                className="hidden"
                disabled={disabled || isCompressing}
              />
              <svg xmlns="http://www.w3.org/2000/svg" className="h-8 w-8 text-gray-400" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 6v6m0 0v6m0-6h6m-6 0H6" />
              </svg>
              <p className="text-sm text-gray-500 mt-1">Add More</p>
            </label>
          )}
        </div>
      ) : (
        <label className="flex flex-col items-center justify-center h-32 cursor-pointer hover:bg-gray-100">
          <input
            type="file"
            accept={type === 'image' ? 'image/*' : 'video/*'}
            onChange={handleFilesChange}
            multiple={multiple}
            className="hidden"
            disabled={disabled || isCompressing}
          />
          {isCompressing ? (
            <div className="text-center">
              <div className="inline-block animate-spin rounded-full h-8 w-8 border-4 border-green-500 border-t-transparent"></div>
              <p className="text-sm text-gray-500 mt-2">Compressing...</p>
              <div className="w-full h-2 bg-gray-200 rounded-full mt-2 max-w-[150px] mx-auto">
                <div 
                  className="h-full bg-green-500 rounded-full transition-all duration-300"
                  style={{ width: `${compressionProgress}%` }}
                ></div>
              </div>
            </div>
          ) : (
            <>
              <svg xmlns="http://www.w3.org/2000/svg" className="h-10 w-10 text-gray-400" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-8l-4-4m0 0L8 8m4-4v12" />
              </svg>
              <p className="text-sm text-gray-500 mt-2">Click to {type === 'image' ? 'upload images' : 'upload video'}</p>
              <p className="text-xs text-gray-400">(Files will be automatically compressed)</p>
            </>
          )}
        </label>
      )}
    </div>
  );
};

export default MediaUploader;
